A={(1,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
B={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# Map input rows 0..8, cols 0..9 into output 10x9, 8 transformations: each orientation using rectangular plane.
transforms={
'cw': {(c,8-r) for r,c in A},
'ccw': {(9-c,r) for r,c in A},
'flip_lr': {(r,9-c) for r,c in A},
'flip_ud': {(8-r,c) for r,c in A},
'transpose': {(c,r) for r,c in A},
'anti-transpose': {(9-c,8-r) for r,c in A},
'180': {(8-r,9-c) for r,c in A},
'identity': A,
}
{n: (s==B, len(s^B)) for n,s in transforms.items()}
